 ER([("(2/3)² = 4/3","(2/3)² = 4/9: también se eleva el denominador"),("−(1/2)² = 1/4","−(1/2)² = −1/4: el signo queda afuera")],["Errores típicos.","Elevar solo el numerador: hay que elevar *los dos*.","Y meter el signo menos adentro de la potencia cuando está afuera del paréntesis."]),
